(
  $component := component_data;
  $action := current_action;

  /* Merge component name and id into the action */
  $merge([
    $action,
    {
      "component_name": $component.name,
      "component_id": $component.id,
      "title": $action.title
    }
  ])
)

(
  /* Extract current loop item and fetched inputs */
  $item := loops.for_each_action_of_playbook.value.item;
  $fetched_inputs := actions.fetch_inputs_of_actions.result.body;
  $current_steps := variables.steps;
  $actions_map := actions.Create_Actions_Map_and_Filter.result.actions_map;
  $fetched_outputs := actions.fetch_outputs_of_actions.result.body ? actions.fetch_outputs_of_actions.result.body : {};

  /* Look up action from map using key */
  $action := $lookup($actions_map, $item.actionName);

  /* Create new step object */
  $new_step := {
    "key": $item.actionName,
    "title": $action.title ? $action.title : "",
    "component_name": $action.component_name ? $action.component_name : "component_name",
    "component_id": $action.component_id ? $action.component_id : "component_id",
    "inputs": $fetched_inputs,
    "outputs": $fetched_outputs,
    "created": $item.created ? $item.created : "",
    "start": $item.start ? $item.start : "",
    "end": $item.end ? $item.end : "",
    "status": $item.status ? $item.status : "",
    "type": $item.type ? $item.type : ""
  };

  /* Ensure current_steps is an array, then append */
  $existing := $type($current_steps) = "array" ? $current_steps : [];
  $updated_steps := $append($existing, $new_step);

  /* Return updated steps array - force array type */
  $type($updated_steps) = "array" ? $updated_steps : [$updated_steps]
)

(
  /* Extract current loop item and fetched inputs */
  $item := loops.for_each_action_of_playbook.value.item;
  $fetched_inputs := actions.fetch_inputs_of_actions.result.body;
  $current_steps := variables.steps;
  $actions_map := actions.Create_Actions_Map_and_Filter.result.actions_map;

  /* Look up action from map using key */
  $action := $lookup($actions_map, $item.actionName);

  /* Create new step object without outputs */
  $new_step := {
    "key": $item.actionName,
    "title": $action.title ? $action.title : "",
    "component_name": $action.component_name ? $action.component_name : "component_name",
    "component_id": $action.component_id ? $action.component_id : "component_id",
    "inputs": $fetched_inputs,
    "outputs": {},
    "created": $item.created ? $item.created : "",
    "start": $item.start ? $item.start : "",
    "end": $item.end ? $item.end : "",
    "status": $item.status ? $item.status : "",
    "type": $item.type ? $item.type : ""
  };

  /* Ensure current_steps is an array, then append */
  $existing := $type($current_steps) = "array" ? $current_steps : [];
  $updated_steps := $append($existing, $new_step);

  /* Return updated steps array - force array type */
  $type($updated_steps) = "array" ? $updated_steps : [$updated_steps]
)

(
  $playbook_actions := actions.Fetch_Playbook_Details.result.body.items[0].item.playbook.actions;

  /* Function to minify a single action */
  $minify_action := function($k, $v) {
    (
      $base := {
        "key": $k,
        "title": $v.title,
        "type": $v.type
      };
      $v.action ? $merge([$base, {"action": $replace($v.action, "$playbook.", "")}]) : $base
    )
  };

  /* Extract top-level actions */
  $top_level := $map($keys($playbook_actions), function($k) {
    $minify_action($k, $lookup($playbook_actions, $k))
  });

  /* Extract nested actions from loop and parallelGroup types (one level deep) */
  $nested := $map($keys($playbook_actions), function($parent_key) {
    (
      $parent := $lookup($playbook_actions, $parent_key);
      /* Check if action has nested actions (loop or parallelGroup) */
      ($parent.type = "loop" or $parent.type = "parallelGroup") and $parent.actions ? 
        $map($keys($parent.actions), function($nested_key) {
          $minify_action($nested_key, $lookup($parent.actions, $nested_key))
        })
      : []
    )
  });

  /* Flatten nested arrays completely */
  $flattened_nested := $reduce($nested, function($acc, $item) {
    $count($item) > 0 ? $append($acc, $item) : $acc
  }, []);

  /* Combine top-level and nested actions */
  $all_actions := $append($top_level, $flattened_nested);

  /* Filter actions where action field exists and is not empty */
  $filter($all_actions, function($action) {
    $action.action and $action.action != ""
  })
)

