# Get inputs
minified = action_inputs.get('minified_actions', [])
enriched = action_inputs.get('enriched_results', [])
fetch_actions = action_inputs.get('fetch_actions_body', {})

# Build actions_map
# Extract enriched_action from each iteration result
flat_enriched = []
for item in enriched:
    if 'Update_Minified_Actions_Output' in item and 'result' in item['Update_Minified_Actions_Output']:
        enriched_action = item['Update_Minified_Actions_Output']['result'].get('enriched_action')
        if enriched_action:
            flat_enriched.append(enriched_action)

# Create map from enriched actions for quick lookup
enriched_map = {}
for action in flat_enriched:
    key = action.get('key')
    if key:
        enriched_map[key] = action

# Update minified actions with enriched data
actions_map = {}
for action in minified:
    key = action.get('key')
    if key:
        if key in enriched_map:
            enriched_item = enriched_map[key]
            actions_map[key] = {
                **action,
                'component_name': enriched_item.get('component_name'),
                'component_id': enriched_item.get('component_id')
            }
        else:
            actions_map[key] = action

# Build filtered_playbook_actions
# Filter for playbook type and non-queued status
items = fetch_actions.get('items', [])
filtered_playbook_actions = []

for item in items:
    item_data = item.get('item', {})
    item_type = item_data.get('type', '').lower()
    item_status = item_data.get('status', '').lower()

    if item_type == 'playbook' and 'queued' not in item_status:
        filtered_playbook_actions.append(item)

# Set outputs
action_outputs = {
    'actions_map': actions_map,
    'filtered_playbook_actions': filtered_playbook_actions
}

